<section class="owner-section-page owner-page template-admin-page"><div class="page-heading"><span class="eyebrow">تحكم كامل</span><h1>إدارة القوالب</h1><p>أوقف استخدام أي قالب فورًا؛ لن يظهر للمستخدمين ولن يقبل التطبيق، وتتحول الملفات المنشورة تلقائيًا إلى قالب آمن.</p></div><?php require __DIR__.'/owner_nav.php'; ?><div class="template-admin-grid"><?php foreach(($allTemplates??[]) as $template): $control=$controlMap[$template['id']]??['is_enabled'=>1,'admin_note'=>'']; $enabled=(int)$control['is_enabled']===1; ?><article class="dashboard-card template-admin-card <?= $enabled?'is-enabled':'is-disabled' ?>"><div class="template-admin-visual template-family-<?= e($template['family']??'orbit') ?>"><span><?= e($template['variant']??'') ?></span><strong><?= e($template['experience']??$template['name']) ?></strong></div><div class="template-admin-copy"><span class="template-category"><?= e($template['role']==='student'?'طالب':($template['role']==='teacher'?'معلم':'مشترك')) ?></span><h2><?= e($template['name']) ?></h2><p>نظام <?= e($template['family']??'orbit') ?> · تخطيط <?= e($template['layout']) ?></p><form method="post" action="/owner/template/toggle" class="template-admin-form"><?= csrf_field() ?><input type="hidden" name="template_id" value="<?= e($template['id']) ?>"><label class="field"><span>ملاحظة</span><input name="admin_note" maxlength="300" value="<?= e($control['admin_note']??'') ?>" placeholder="سبب الإيقاف اختياري"></label><?php if($enabled): ?><label class="toggle-field"><input type="checkbox" name="disable" value="1"><span>إيقاف استخدام هذا القالب</span></label><button class="button button-quiet" type="submit">حفظ / إيقاف القالب</button><?php else: ?><button class="button button-gold" type="submit">إعادة تفعيل القالب</button><?php endif; ?></form></div></article><?php endforeach; ?></div></section>